import {
  kpiUsesTopBottomReportType,
  ReportType,
} from 'pages/pillars/ValueCreation/VolumePages/config/reportType';
import { Kpi } from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { GrowthLeverSectionMainSubFilters } from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/components/GrowthLeverSection/types';
import { GrowthLeverMainSubFilters } from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/constants/growthLevers';

type GrowthLeverRuntimeFilters = {
  dt_end: string | null | undefined;
  kpi: Kpi;
  reporttype: ReportType;
};

export const buildGrowthLeverMainSubFilters = (
  mainSubFilters: GrowthLeverMainSubFilters,
  { dt_end, kpi, reporttype }: GrowthLeverRuntimeFilters,
): GrowthLeverSectionMainSubFilters => ({
  ...mainSubFilters,
  kpi,
  bigNumbers: {
    ...mainSubFilters.bigNumbers,
    dt_end,
    kpi,
  },
  topBottomBrands: {
    ...mainSubFilters.topBottomBrands,
    dt_end,
    kpi,
    ...(kpiUsesTopBottomReportType(kpi) ? { reporttype } : {}),
  },
});
